const raw  = tf.tensor1d([10, 20, 30]);
const tare = tf.tensor1d([1, 2, 3]);

console.log(raw.sub(tare));         // elementwise subtract
console.log(raw.sub(tare).mul(2));  // chain: subtract, then scale
console.log(raw.div(10));           // a scalar broadcasts
console.log(tf.add(raw, tare));     // functional form, same result

const batch   = tf.tensor2d([[1, 2], [3, 4], [5, 6]]); // [3, 2]
const weights = tf.tensor2d([[10], [20]]);              // [2, 1]

console.log(tf.matMul(batch, weights).shape);   // [3, 2] · [2, 1] → [3, 1]
console.log(tf.matMul(batch, weights).arraySync());

// [a, b] · [b, c] → [a, c] — inner dims must agree:
console.log(tf.tensor2d([[1, 2, 3], [4, 5, 6]]).matMul(
  tf.tensor2d([[1, 0], [0, 1], [1, 1]])).shape);      // [2, 3] · [3, 2] → [2, 2]

try {
  tf.matMul(tf.ones([2, 3]), tf.ones([4, 5]));        // 3 ≠ 4
} catch (e) {
