const counter = tf.variable(tf.zeros([1]), true, "counter");
console.log("start:", counter);
counter.assign(tf.tensor1d([10]));
console.log("after assign:", counter);
// tf.js has no assignAdd/assignSub — compose them from ops:
counter.assign(counter.add(tf.tensor1d([5])));
console.log("after +5:", counter);
counter.assign(counter.sub(tf.tensor1d([3])));
console.log("after -3:", counter);

const dSquare = tf.grad(x => x.mul(x)); // f(x) = x²  → f'(x) = 2x
console.log("f'(3):", dSquare(tf.scalar(3)));
const dCube = tf.grad(x => x.mul(x).mul(x)); // f(x) = x³  → f'(x) = 3x²
console.log("f'(2):", dCube(tf.scalar(2)));
const vg = tf.valueAndGrad(x => x.mul(x)); // value AND gradient in one pass
const { value, grad } = vg(tf.scalar(4));
console.log("f(4) =", value.dataSync()[0], "f'(4) =", grad.dataSync()[0]);

const w = tf.variable(tf.scalar(0), true, "w"); // learnable weight
const sgd = tf.train.sgd(0.2); // optimizer, learning rate 0.2
const loss = () => w.sub(tf.scalar(4)).square(); // L(w) = (w − 4)²
for (let step = 0; step < 6; step++) {
  const l = sgd.minimize(loss, true, [w]); // returns the PRE-update cost
  console.log(`step ${step}: loss=${l.dataSync()[0].toFixed(3)}, w=${w.dataSync()[0].toFixed(3)}`);
}

const before = tf.memory().numTensors; // session state varies — count the DELTA
const kept = tf.tidy(() => {
  const a = tf.tensor1d([1, 2, 3]); // intermediate
  const b = a.square(); // intermediate
  return b.mean(); // returned tensors survive tidy
});
console.log("survivor:", kept);
const v = tf.tidy(() => tf.variable(tf.scalar(9)));
console.log("variables survive tidy too:", v);
console.log("kept after tidy (session-independent):", tf.memory().numTensors - before);

