const d = await loadData("circles");
const xs = tf.tensor2d(d.x);                      // [300, 2]
const ys = tf.tensor2d(d.y, [d.y.length, 1]);     // [300, 1]

const model = tf.sequential();
model.add(tf.layers.dense({ inputShape: [2], units: 8, activation: "relu",
  kernelInitializer: tf.initializers.glorotUniform({ seed: 42 }) }));
model.add(tf.layers.dense({ units: 1, activation: "sigmoid",
  kernelInitializer: tf.initializers.glorotUniform({ seed: 43 }) }));
model.compile({ optimizer: tf.train.adam(0.02), loss: "binaryCrossentropy", metrics: ["accuracy"] });

const h = await model.fit(xs, ys, { epochs: 40, batchSize: 32, shuffle: false, verbose: 0 });

console.log("history keys:", JSON.stringify(Object.keys(h.history).sort()));
console.log("epoch  1 loss:", Number(h.history.loss[0].toFixed(4)), "acc:", Number(h.history.acc[0].toFixed(4)));
console.log("epoch 40 loss:", Number(h.history.loss[39].toFixed(4)), "acc:", Number(h.history.acc[39].toFixed(4)));

const [loss, acc] = await model.evaluate(xs, ys, { batchSize: 300 });
console.log("evaluate -> loss:", Number(loss.dataSync()[0].toFixed(4)), "acc:", Number(acc.dataSync()[0].toFixed(4)));

