const xs = tf.tensor2d([[0], [1], [2], [3], [4], [5], [6], [7]]);
const ys = tf.tensor2d([[1], [3], [5], [7], [9], [11], [13], [15]]); // y = 2x + 1

function seededNet() {
  const m = tf.sequential();
  m.add(tf.layers.dense({ inputShape: [1], units: 1,
    kernelInitializer: tf.initializers.glorotUniform({ seed: 7 }),
    biasInitializer: tf.initializers.zeros() }));
  return m;
}
async function run(lr, epochs = 30) {
  const m = seededNet();
  m.compile({ optimizer: tf.train.sgd(lr), loss: "meanSquaredError" });
  const h = await m.fit(xs, ys, { epochs, batchSize: 8, shuffle: false, verbose: 0 });
  const L = h.history.loss;
  return { first: L[0], last: L[L.length - 1] };
}
const timid = await run(0.001);
const right = await run(0.01);
const wild  = await run(1);
console.log("lr=0.001 (too small):", Number(timid.first.toFixed(2)), "->", Number(timid.last.toFixed(2)));
console.log("lr=0.01  (just right):", Number(right.first.toFixed(2)), "->", Number(right.last.toFixed(4)));
console.log("lr=1     (too big):  ", Number(wild.first.toFixed(2)), "->", wild.last, "· NaN?", Number.isNaN(wild.last));

