}
async function trainLosses(opt, epochs = 60) {
  const m = seededNet();
  m.compile({ optimizer: opt, loss: "meanSquaredError" });
  const h = await m.fit(xs, ys, { epochs, batchSize: 6, shuffle: false, verbose: 0 });
  return h.history.loss;
}
const sgdL  = await trainLosses(tf.train.sgd(0.1));
const adamL = await trainLosses(tf.train.adam(0.1));

