console.log("epoch 10 — sgd:", Number(sgdL[9].toFixed(4)), "· adam:", Number(adamL[9].toFixed(4)));
console.log("epoch 60 — sgd:", Number(sgdL[59].toFixed(6)), "· adam:", Number(adamL[59].toFixed(6)));
const below = L => L.findIndex(v => v < 0.05) + 1;
