// 80 samples; every 3rd TRAINING label got flipped by a sensor glitch.
// The net memorizes the noise: train loss keeps falling while
// val_loss bottoms out and then rises — textbook overfitting.
const d = await loadData("circles");
const N = 80, SPLIT = 0.25;
const trainN = Math.floor(N * (1 - SPLIT));
const x = d.x.slice(0, N).map(r => r.slice());
const y = d.y.slice(0, N).map(v => v);
for (let i = 0; i < trainN; i += 3) y[i] = 1 - y[i]; // glitched training labels
const xs = tf.tensor2d(x);
const ys = tf.tensor2d(y, [N, 1]);

function noisyModel() {
  const m = tf.sequential();
  m.add(tf.layers.dense({ inputShape: [2], units: 32, activation: "relu",
    kernelInitializer: tf.initializers.glorotUniform({ seed: 42 }) }));
  m.add(tf.layers.dense({ units: 32, activation: "relu",
    kernelInitializer: tf.initializers.glorotUniform({ seed: 7 }) }));
  m.add(tf.layers.dense({ units: 1, activation: "sigmoid",
    kernelInitializer: tf.initializers.glorotUniform({ seed: 99 }) }));
  m.compile({ optimizer: tf.train.adam(0.01), loss: "binaryCrossentropy", metrics: ["acc"] });
  return m;
}

const h1 = await noisyModel().fit(xs, ys, {
  epochs: 40, batchSize: 16, shuffle: false, validationSplit: SPLIT, verbose: 0,
});
console.log("no early stopping ->", h1.epoch.length, "epochs");
console.log("best val_loss at epoch", h1.history.val_loss.indexOf(Math.min(...h1.history.val_loss)));

const h2 = await noisyModel().fit(xs, ys, {
  epochs: 40, batchSize: 16, shuffle: false, validationSplit: SPLIT, verbose: 0,
  callbacks: [tf.callbacks.earlyStopping({ monitor: "val_loss", patience: 2 })],
});
console.log("patience=2        ->", h2.epoch.length, "epochs");

class LossWatcher extends tf.Callback {
  constructor() { super(); this.losses = []; }
  onEpochEnd(epoch, logs) {
    // logs values can be Scalar tensors depending on callback order:
    const v = typeof logs.loss === "number" ? logs.loss : logs.loss.dataSync()[0];
    this.losses.push(Number(v.toFixed(4)));
  }
}

