// identical seeds — the ONLY difference is the l2 tax on the kernels
function buildSeeded(reg) {
  const model = tf.sequential();
  model.add(tf.layers.dense({
    inputShape: [2], units: 8, activation: "relu",
    kernelInitializer: tf.initializers.glorotUniform({ seed: 42 }),
    kernelRegularizer: reg ? tf.regularizers.l2({ l2: reg }) : null,
  }));
  model.add(tf.layers.dense({
    units: 1, activation: "sigmoid",
    kernelInitializer: tf.initializers.glorotUniform({ seed: 7 }),
    kernelRegularizer: reg ? tf.regularizers.l2({ l2: reg }) : null,
  }));
  model.compile({ optimizer: tf.train.sgd(0.5), loss: "binaryCrossentropy", metrics: ["acc"] });
  return model;
}

const hPlain = await buildSeeded(0).fit(xs, ys, { epochs: 1, batchSize: 32, shuffle: false, verbose: 0 });
const hL2 = await buildSeeded(0.01).fit(xs, ys, { epochs: 1, batchSize: 32, shuffle: false, verbose: 0 });
console.log("plain loss[0]:   ", hPlain.history.loss[0].toFixed(4));
console.log("l2(0.01) loss[0]:", hL2.history.loss[0].toFixed(4));

// evaluate() sees only the data loss — the penalty is NOT included
const e1 = await buildSeeded(0).evaluate(xs, ys, { batchSize: 300 });
const e2 = await buildSeeded(0.01).evaluate(xs, ys, { batchSize: 300 });
console.log("evaluate plain:", e1[0].dataSync()[0].toFixed(4), "evaluate l2:", e2[0].dataSync()[0].toFixed(4));

