blocks.code:
// one toy sentence, hand-set 4-d vectors (d = 4) — self-attention: Q = K = X
const X = tf.tensor2d([
  [0.2, 0,   2.0, 0.2],   // "the"
  [2.2, 0.4, 0,   0  ],   // "cat"
  [0.4, 2.2, 0,   0  ],   // "sat"
  [0,   0.2, 0.4, 1.8],   // "on"
  [2.0, 0,   0,   0.6],   // "mat"
]);
const d = 4;

const raw = tf.matMul(X, X, false, true);             // Q·Kᵀ — transposeB flips K
const scores = tf.div(raw, tf.scalar(Math.sqrt(d)));  // scaled by √d

const row = (t, i) => t.slice([i, 0], [1, 5]).arraySync()[0].map(v => Number(v.toFixed(4)));
console.log("'the' raw scores:", JSON.stringify(row(raw, 0)));
console.log("'the' scaled (÷√4=2):", JSON.stringify(row(scores, 0)));
console.log("'cat' raw:", JSON.stringify(row(raw, 1)), "scaled:", JSON.stringify(row(scores, 1)));
console.log("'sat' raw:", JSON.stringify(row(raw, 2)), "scaled:", JSON.stringify(row(scores, 2)));

// same sentence and scores as above (each cell is self-contained)
const X = tf.tensor2d([[0.2,0,2.0,0.2],[2.2,0.4,0,0],[0.4,2.2,0,0],[0,0.2,0.4,1.8],[2.0,0,0,0.6]]);
const scores = tf.div(tf.matMul(X, X, false, true), tf.scalar(2));   // d = 4

const weights = tf.softmax(scores, -1);        // each ROW sums to 1
const w = weights.arraySync();
const toks = ["the", "cat", "sat", "on", "mat"];
console.log("attention weights (3dp):");
for (let i = 0; i < 5; i++) console.log("  " + toks[i].padEnd(4), w[i].map(v => v.toFixed(3)).join(" "));
console.log("row sums:", weights.sum(1).arraySync().map(v => Number(v.toFixed(6))).join(" "));
console.log("all weights in [0,1]:", w.every(r => r.every(v => v >= 0 && v <= 1)));

const context = tf.matMul(weights, X);          // each row: weighted mix of value rows
console.log("'cat' context row:", context.slice([1, 0], [1, 4]).arraySync()[0].map(v => Number(v.toFixed(4))));

const X = tf.tensor2d([[0.2,0,2.0,0.2],[2.2,0.4,0,0],[0.4,2.2,0,0],[0,0.2,0.4,1.8],[2.0,0,0,0.6]]);
const scores = tf.div(tf.matMul(X, X, false, true), tf.scalar(2));   // d = 4
const unmasked = tf.softmax(scores, -1).arraySync();

const n = 5;
const causal = tf.tensor2d(Array.from({ length: n }, (_, i) =>
  Array.from({ length: n }, (_, j) => (j <= i ? 0 : -1e9))));   // future = -1e9
const masked = tf.softmax(scores.add(causal), -1).arraySync();

console.log("unmasked 'sat':", unmasked[2].map(v => v.toFixed(3)).join(" "));
console.log("masked   'sat':", masked[2].map(v => v.toFixed(3)).join(" "));
console.log("'the' can only see itself:", JSON.stringify(masked[0]) === "[1,0,0,0,0]");
console.log("future weights are exactly 0:", masked.every((r, i) => r.every((v, j) => j > i ? v === 0 : true)));
console.log("last row unchanged (it sees everything):", JSON.stringify(masked[4]) === JSON.stringify(unmasked[4]));

